    op.execute(sa.text("ALTER TABLE reviewer_assignment DROP CONSTRAINT uq_reviewer_assignment_lecturer_id_proposal_id_thesis_i_15ea"))
    op.execute(sa.text("ALTER TABLE reviewer_assignment ADD CONSTRAINT ck_reviewer_assignment_scope_matches_subject CHECK ((review_scope = 'PROPOSAL' AND proposal_id IS NOT NULL) OR (review_scope = 'THESIS' AND thesis_id IS NOT NULL))"))
