    op.execute(sa.text("CREATE UNIQUE INDEX uq_reviewer_assignment_thesis ON reviewer_assignment (lecturer_id, thesis_id) WHERE thesis_id IS NOT NULL AND state = 'ACTIVE'"))

    # Mẫu 6: ba nhóm điểm có tiêu chí con và một mục điểm thưởng độc lập.
    op.execute(sa.text("ALTER TABLE rubric_criterion ADD COLUMN parent_id UUID"))
    op.execute(sa.text("ALTER TABLE rubric_criterion ADD CONSTRAINT fk_rubric_criterion_parent_id_rubric_criterion FOREIGN KEY (parent_id) REFERENCES rubric_criterion (id) ON DELETE RESTRICT"))
    op.execute(sa.text("ALTER TABLE rubric_criterion ADD CONSTRAINT ck_rubric_criterion_not_self_parent CHECK (parent_id IS NULL OR parent_id <> id)"))
    op.execute(sa.text("ALTER TABLE rubric_criterion DROP CONSTRAINT ck_rubric_criterion_criterion_type"))
    op.execute(sa.text("ALTER TABLE rubric_criterion ADD CONSTRAINT ck_rubric_criterion_criterion_type CHECK (criterion_type IN ('GROUP','NORMAL','BONUS'))"))
    op.execute(sa.text("ALTER TABLE document_version DROP CONSTRAINT ck_document_version_state"))
    op.execute(sa.text("ALTER TABLE document_version ADD CONSTRAINT ck_document_version_state CHECK (state IN ('DRAFT','SUBMITTED','RESULT_AVAILABLE','REVISION_REQUESTED','ACCEPTED','FINAL','SUPERSEDED'))"))
    op.execute(sa.text("ALTER TABLE topic_registration DROP CONSTRAINT ck_topic_registration_state"))
    op.execute(sa.text("ALTER TABLE topic_registration ADD CONSTRAINT ck_topic_registration_state CHECK (state IN ('DRAFT','SUBMITTED','LECTURER_ACCEPTED','LECTURER_REJECTED','RETURNED','FINALIZED','CANCELLED'))"))
